n16570.content:
\begin{theorem}\label{thm:localized_holder_modification}
  \uses{def:IsKolmogorovProcess, def:HasBoundedCoveringNumberCover}
  \leanok
  \lean{ProbabilityTheory.exists_modification_holder'}
Let $T$ be a metric space with a cover $(T_n)$ with bounded covering numbers with constants $c_n$ and the same exponent $d$.
Let $X : T \to \Omega \to E$ be a process that satisfies the Kolmogorov condition with exponents $(p, q)$ with $q > d$.
Then $X$ has a modification $Y$ such that almost surely the paths of $Y$ are locally Hölder continuous of all orders $\gamma \in (0, (q - d)/p)$.
\end{theorem}

n16571.content:
\begin{proof}\leanok
  \uses{thm:holder_modification, lem:indistinguishable_of_modification_of_continuous}
For each $n$, by Theorem~\ref{thm:holder_modification} there is a modification $Y_n$ of $X$ seen as a process on $T_n$ such that the paths of $Y_n$ are Hölder continuous of all orders $\gamma \in (0, (q - d)/p)$.
By Lemma~\ref{lem:indistinguishable_of_modification_of_continuous}, $Y_n$ and $Y_{n+1}$ are indistinguishable on $T_n$.
That is, almost surely $Y_n = Y_{n+1}$ on $T_n$.
Since there are countably many such almost sure equalities, we get that almost surely there is equality for all $n$.
Let $A$ be the event that this happens, let $x_0 \in E$ be arbitrary and define a process $Y : T \to \Omega \to E$ by
\begin{align*}
  Y(t, \omega)
  &= \begin{cases}
    Y_n(t, \omega) & \text{if } \omega \in A \: , \: t \in T_n \setminus T_{n-1} \: ,
    \\
    x_0 & \text{if } \omega \notin A \: .
  \end{cases}
\end{align*}
Then $Y$ is a modification of $X$ and has paths that are locally Hölder continuous of all orders $\gamma \in (0, (q - d)/p)$ almost surely.
\end{proof}

n16572.content:
\begin{theorem}\label{thm:localized_holder_modification_sup}
  \uses{def:IsKolmogorovProcess, def:HasBoundedCoveringNumberCover}
  \leanok
  \lean{ProbabilityTheory.exists_modification_holder_iSup}
Let $T$ be a metric space with a cover $(T_n)$ with bounded covering numbers with constants $c_n$ and the same exponent $d$.
Let $(p_n, q_n)_{n \in \mathbb{N}}$ be a sequence of pairs of positive numbers such that $q_n > d$ for all $n \in \mathbb{N}$.
Let $X : T \to \Omega \to E$ be a process that satisfies the Kolmogorov condition with exponents $(p_n, q_n)$ for all $n \in \mathbb{N}$.
Then $X$ has a modification $Y$ such that almost surely the paths of $Y$ are locally Hölder continuous of all orders $\gamma \in (0, \sup_n (q_n - d)/p_n)$.
\end{theorem}

n16574.content:
\begin{definition}[pre-Brownian process]\label{def:preBrownian}
  \uses{def:gaussianLimit}
  \leanok
  \lean{ProbabilityTheory.preBrownian}
Let $\Omega = \mathbb{R}^{\mathbb{R}_+}$ and consider the probability space $(\Omega, P_B)$ (where $P_B$ is the measure defined in Definition~\ref{def:gaussianLimit}).
The identity on that space is a function $\Omega \to \mathbb{R}_+ \to \mathbb{R}$.
We reorder the arguments to define a stochastic process $X : \mathbb{R}_+ \to \Omega \to \mathbb{R}$, which we call the pre-Brownian process.
\end{definition}

n16575.content:
\begin{lemma}\label{lem:isGaussianProcess_preBrownian}
  \uses{def:preBrownian, def:IsGaussianProcess}
  \leanok
  \lean{ProbabilityTheory.isGaussianProcess_preBrownian}
  The pre-Brownian process $X$ of Definition~\ref{def:preBrownian} is a Gaussian process.
\end{lemma}

n16576.content:
\begin{proof}\leanok
  \uses{lem:isGaussian_multivariateGaussian}
For any $t_1, \ldots, t_n \in \mathbb{R}_+$, the distribution of $(X_{t_1}, \ldots, X_{t_n})$ is given by a finite-dimensional distribution of $P_B$, and therefore is Gaussian.
\end{proof}

n16577.content:
\begin{lemma}\label{lem:hasLaw_preBrownian_sub}
  \uses{def:preBrownian}
  \leanok
  \lean{ProbabilityTheory.hasLaw_preBrownian_sub}
Let $X$ be the pre-Brownian process of Definition~\ref{def:preBrownian}.
Then, for all $s, t \in \mathbb{R}_+$, the random variable $X_t - X_s$ is a Gaussian random variable with mean $0$ and variance $|t - s|$.
\end{lemma}

n16578.content:
\begin{proof}\leanok
  \uses{lem:isGaussianProcess_preBrownian, lem:isGaussian_map}
The map
\begin{align*}
  L : \mathbb{R}^2 &\to \mathbb{R} \\
  (x_1, x_2) &\mapsto x_2 - x_1
\end{align*}
is a continuous linear map, and $(X_s, X_t)$ is Gaussian by Lemma~\ref{lem:isGaussianProcess_preBrownian}, therefore $X_t - X_s$ is Gaussian by Lemma~\ref{lem:isGaussian_map}. By definition of $P_B$, we have
$$\mathbb{E}[X_t - X_s] = \mathbb{E}[X_t] - \mathbb{E}[X_s] = 0 - 0 = 0,$$
and
$$\mathrm{Var}(X_t - X_s) = \mathrm{Var}(X_t) - 2\mathrm{Cov}(X_t, X_s) + \mathrm{Var}(X_s) = t - 2(t \land s) + s = t \lor s - t \land s = |t - s|.$$
Therefore $X_t - X_s$ is Gaussian with mean $0$ and variance $|t - s|$.
\end{proof}

n16579.content:
\begin{lemma}\label{lem:isKolmogorovProcess_preBrownian}
  \uses{def:preBrownian}
  \leanok
  \lean{ProbabilityTheory.isKolmogorovProcess_preBrownian}
The pre-Brownian process $X$ of Definition~\ref{def:preBrownian} satisfies the Kolmogorov condition for exponents $(2n,n)$ with constant $(2n - 1)!!$ for all $n \in \mathbb{N}$.
That is, for all $s, t \in \mathbb{R}_+$, we have
\begin{align*}
  \mathbb{E} \left[ |X_t - X_s|^{2n} \right] \le (2n - 1)!! |t - s|^n
  \: .
\end{align*}
\end{lemma}

n16580.content:
\begin{proof}\leanok
  \uses{lem:centralMoment_two_mul_gaussianReal, lem:hasLaw_preBrownian_sub}
$X_t - X_s$ is a Gaussian random variable with mean $0$ and variance $|t - s|$ (Lemma~\ref{lem:hasLaw_preBrownian_sub}).
Thus, by Lemma~\ref{lem:centralMoment_two_mul_gaussianReal}, we have
\begin{align*}
  \mathbb{E} \left[ |X_t - X_s|^{2n} \right]
  = (2n - 1)!! |t - s|^n
  \: .
\end{align*}
\end{proof}

n16581.content:
\begin{definition}[Brownian motion]\label{def:brownian}
  \uses{thm:localized_holder_modification_sup, def:preBrownian, lem:isKolmogorovProcess_preBrownian, lem:hasBoundedCoveringNumberCover_nnreal}
  \leanok
  \lean{ProbabilityTheory.brownian}
By Theorem~\ref{thm:localized_holder_modification_sup}, there exists a modification $B$ of the pre-Brownian process such that all the paths of $B$ are Hölder continuous of all orders $\gamma \in (0, 1/2)$.
We call $B$ the \emph{Brownian motion} on $\mathbb{R}_+$.
\end{definition}

n16582.content:
\begin{lemma}\label{lem:isGaussianProcess_brownian}
  \uses{def:brownian, def:IsGaussianProcess}
  \leanok
  \lean{ProbabilityTheory.isGaussianProcess_brownian}
The Brownian motion is a Gaussian process.
\end{lemma}

n16583.content:
\begin{proof}\leanok
  \uses{lem:isGaussianProcess_of_modification, lem:isGaussianProcess_preBrownian}
The pre-Brownian process is a Gaussian process by Lemma~\ref{lem:isGaussianProcess_preBrownian}.
The Brownian motion is a modification of the pre-Brownian process by Definition~\ref{def:brownian}.
Thus, the Brownian motion is a Gaussian process as well by Lemma~\ref{lem:isGaussianProcess_of_modification}.
\end{proof}

n16584.content:
\begin{lemma}\label{lem:isHolderWith_brownian}
  \uses{def:brownian}
  \leanok
  \lean{ProbabilityTheory.memHolder_brownian}
The paths of the Brownian motion are locally Hölder continuous of all orders $\gamma \in (0, 1/2)$.
\end{lemma}

n16585.content:
\begin{proof}\leanok
  \uses{lem:hasBoundedCoveringNumberCover_nnreal, lem:isKolmogorovProcess_preBrownian, thm:localized_holder_modification_sup}
Consider the cover of $\mathbb{R}_+$ given by $T_n := [0, n + 1)$. By Lemma~\ref{lem:hasBoundedCoveringNumberCover_nnreal}, this cover has bounded covering numbers with exponent $1$. Moreover, by Lemma~\ref{lem:isKolmogorovProcess_preBrownian}, the pre-Brownian process satisfies the Kolmogorov condition with exponents $(2n + 4, n + 2)$ for all $n \in \mathbb{N}$.
In particular, for all $n \in \mathbb{N}$, $2n + 4 > 1$. Applying Theorem~\ref{thm:localized_holder_modification_sup} we deduce that the modification used in Definition~\ref{def:brownian} has locally Hölder continuous paths for all orders $\gamma \in (0, \sup_n (n + 1) / (2n + 4))$.
Clearly for all $n \in \mathbb{N}$ we have $(n + 1) / (2n + 4) \leqslant 2$, and this quantity tends to $2$ as $n$ goes to infinity. Therefore the Brownian motion has Hölder continuous paths of order $\gamma$ for all $\gamma \in (0, 1 / 2)$.
\end{proof}

n16586.content:
\begin{lemma}\label{lem:continuous_brownian}
  \uses{def:brownian}
  \leanok
  \lean{ProbabilityTheory.continuous_brownian}
The paths of the Brownian motion are continuous.
\end{lemma}

n16587.content:
\begin{proof}\leanok
  \uses{lem:isHolderWith_brownian}
The paths are $1/4$-Hölder continuous by Lemma~\ref{lem:isHolderWith_brownian} because $0 < 1/4 < 1/2$, therefore they are continuous.
\end{proof}

n16588.content:
\begin{lemma}\label{lem:hasLaw_brownian_eval}
  \uses{def:brownian}
  \leanok
  \lean{ProbabilityTheory.hasLaw_brownian_eval}
For $t \in \mathbb{R}_+$, the law of $B_t$ (the Brownian motion at time $t$) is the real Gaussian measure $\mathcal{N}(0,t)$.
\end{lemma}

n16589.content:
\begin{proof}\leanok
  \uses{def:gaussianLimit}
The Brownian motion $B$ is a modification of the pre-Brownian process, and therefore has same finite dimensional distributions. By Definition~\ref{def:gaussianLimit}, $B_t$ has law $\mathcal{N}(0,t)$.
\end{proof}

n16590.content:
\begin{lemma}\label{lem:hasLaw_brownian_sub}
  \uses{def:brownian}
  \leanok
  \lean{ProbabilityTheory.hasLaw_brownian_sub}
For $s, t \in \mathbb{R}_+$, the law of $B_t - B_s$ is the real Gaussian measure $\mathcal{N}(0,\vert t - s \vert)$.
\end{lemma}

n16591.content:
\begin{proof}\leanok
  \uses{lem:hasLaw_preBrownian_sub}
The Brownian motion $B$ is a modification of the pre-Brownian process, and therefore has same finite dimensional distributions. By Lemma~\ref{lem:hasLaw_preBrownian_sub}, $B_t - B_s$ has law $\mathcal{N}(0,\vert t - s \vert)$.
\end{proof}

n16592.content:
\begin{definition}\label{def:HasIndepIncrements}
  \leanok
  \lean{ProbabilityTheory.HasIndepIncrements}
We say that a stochastic process $X : T \to \Omega \to E$ has independent increments if for all $t_1, \ldots, t_n \in T$ with $t_1 \le t_2 \le \cdots \le t_n$, the random variables $X_{t_2} - X_{t_1}, X_{t_3} - X_{t_2}, \ldots, X_{t_n} - X_{t_{n-1}}$ are independent.
\end{definition}

n16593.content:
\begin{lemma}\label{lem:hasIndepIncrements_brownian}
  \uses{def:brownian, def:HasIndepIncrements}
  \leanok
  \lean{ProbabilityTheory.hasIndepIncrements_brownian}
The Brownian motion has independent increments.
\end{lemma}

n16595.content:
\begin{definition}[Auxiliary Wiener measure]\label{def:wienerMeasureAux}
  \uses{def:brownian, def:gaussianLimit, lem:continuous_brownian}
  \leanok
  \lean{ProbabilityTheory.wienerMeasureAux}
The pushforward of the measure $P_B$ of Definition~\ref{def:gaussianLimit} by the Brownian motion $B$ is a measure on the continuous functions on $\mathbb{R}^{\mathbb{R}_+}$, with the sigma-algebra induced by the product sigma-algebra on $\mathbb{R}^{\mathbb{R}_+}$.
\end{definition}

n16596.content:
\begin{theorem}\label{thm:ContinuousMap.borel_eq_iSup_comap_eval}
  \leanok
  \lean{ProbabilityTheory.ContinuousMap.borel_eq_iSup_comap_eval}
The Borel sigma-algebra on $C(\mathbb{R}_+, \mathbb{R})$ coming from the compact-open topology is equal to the smallest sigma-algebra for which the evaluation maps $f \mapsto f(t)$ are measurable for every $t \in \mathbb{R}_+$.
\end{theorem}

n16598.content:
\begin{definition}\label{def:MeasurableEquiv.continuousMap}
  \uses{thm:ContinuousMap.borel_eq_iSup_comap_eval}
  \leanok
  \lean{ProbabilityTheory.MeasurableEquiv.continuousMap}
The identity is a measurable equivalence between the continuous functions of $\mathbb{R}^{\mathbb{R}_+}$ with the subset sigma-algebra obtained from the product sigma-algebra, and $C(\mathbb{R}_+, \mathbb{R})$ with the Borel sigma-algebra coming from the compact-open topology.

Mathematically this says nothing more than the equality of sigma-algebras of Theorem~\ref{thm:ContinuousMap.borel_eq_iSup_comap_eval} but in Lean we have two different types so we need an equivalence.
\end{definition}

n16599.content:
\begin{definition}[Wiener measure]\label{def:wienerMeasure}
  \uses{def:MeasurableEquiv.continuousMap, def:wienerMeasureAux}
  \leanok
  \lean{ProbabilityTheory.wienerMeasure}
The Wiener measure on $C(\mathbb{R}_+, \mathbb{R})$ with the Borel sigma-algebra is the map of the auxiliary Wiener measure by the measurable equivalence of definition~\ref{def:MeasurableEquiv.continuousMap}.
\end{definition}

n16600.content:
\begin{definition}[Filtration]\label{def:filtration}
  \mathlibok
  \lean{MeasureTheory.Filtration}
A filtration on a measurable space $(\Omega, \mathcal{A})$ with measure $P$ indexed by a preordered set $T$ is a family of sigma-algebras $\mathcal{F} = (\mathcal{F}_t)_{t \in T}$ such that for all $i \le j$, $\mathcal{F}_i \subseteq \mathcal{F}_j$ and for all $t \in T$, $\mathcal{F}_t \subseteq \mathcal{A}$.
\end{definition}

n16601.content:
\begin{definition}\label{def:adapted}
  \uses{def:filtration}
  \mathlibok
  \lean{MeasureTheory.Adapted}
A process $X : T \to \Omega \to E$ is said to be adapted with respect to a filtration $\mathcal{F}$ if for all $t \in T$, $X_t$ is $\mathcal{F}_t$-measurable.
\end{definition}

n16602.content:
\begin{definition}[Progressively measurable]\label{def:IsStronglyProgressive}
  \uses{def:filtration}
  \mathlibok
  \lean{MeasureTheory.IsStronglyProgressive}
A stochastic process $X$ is said to be progressively measurable with respect to a filtration $\mathcal{F}$ if at each point in time $i$, $X$ restricted to $(-\infty, i] \times \Omega$ is measurable with respect to the product $\sigma$-algebra where the $\sigma$-algebra used for $\Omega$ is $\mathcal{F}_i$.
\end{definition}

n16603.content:
\begin{definition}[Right continuous function]\label{def:RightContinuous}
  \leanok
  \lean{IsRightContinuous}
  Let $T$ be equipped with a partial order and $f : T \to E$ be a function. Then $f$ is right
  continuous if for all $t \in T$, $\lim_{s \downarrow t} f(s) = f(t)$.
\end{definition}

n16604.content:
\begin{definition}[Cadlag function]\label{def:IsCadlag}
  \uses{def:RightContinuous}
  \leanok
  \lean{IsCadlag}
  A function $f : T \to E$ is cadlag if it is right continuous and the limit $\lim_{s \uparrow t} f(s)$ exists for all $t \in T$.
\end{definition}

n16605.content:
\begin{lemma}\label{lem:Adapted.isStronglyProgressive_of_rightContinuous}
  \uses{def:adapted, def:IsStronglyProgressive, def:RightContinuous}
  \leanok
  \lean{MeasureTheory.StronglyAdapted.isStronglyProgressive_of_rightContinuous}
Suppose $T$ is a linearly ordered set equipped with the order topology. If $T$ is second countable and a stochastic process $(X_t)_{t \in T}$ is right continuous and adapted, then it is progressively measurable.
\end{lemma}

n16607.content:
\begin{definition}[Martingale]\label{def:Martingale}
  \uses{def:adapted}
  \mathlibok
  \lean{MeasureTheory.Martingale}
Let $\mathcal{F}$ be a filtration on a measurable space $\Omega$ with measure $P$ indexed by $T$.
A family of functions $M : T \to \Omega \to E$ is a martingale with respect to a filtration $\mathcal{F}$ if $M$ is adapted with respect to $\mathcal{F}$ and for all $i \le j$, $P[M_j \mid \mathcal{F}_i] = M_i$ almost surely.
\end{definition}

n16608.content:
\begin{definition}[Submartingale]\label{def:Submartingale}
  \uses{def:adapted}
  \mathlibok
  \lean{MeasureTheory.Submartingale}
Let $\mathcal{F}$ be a filtration on a measurable space $\Omega$ with measure $P$ indexed by $T$.
A family of functions $M : T \to \Omega \to E$ is a submartingale with respect to a filtration $\mathcal{F}$ if $M$ is adapted with respect to $\mathcal{F}$ and for all $i \le j$, $P[M_j \mid \mathcal{F}_i] \ge M_i$ almost surely.
\end{definition}

n16609.content:
\begin{lemma}\label{lem:condExp_sub_nonneg}
  \uses{def:Submartingale}
  \mathlibok
  \lean{MeasureTheory.Submartingale.condExp_sub_nonneg}
Let $X$ be a real-valued submartingale with respect to a filtration $\mathcal{F}$. Then for all $i \le j$, we have $0 \le P[M_j - M_i \mid \mathcal{F}_i]$ almost surely.
\end{lemma}

n16611.content:
\begin{lemma}\label{lem:Submartingale.integrable_stoppedValue}
  \uses{def:Submartingale, def:stoppedProcess}
  \mathlibok
  \lean{MeasureTheory.Submartingale.integrable_stoppedValue}
Let $X$ be a submartingale. Then for all bounded stopping times $\tau$, the stopped value $X_\tau$ is integrable.
\end{lemma}

n16613.content:
\begin{lemma}\label{lem:Martingale.congr}
  \uses{def:Martingale, def:adapted}
  \leanok
  \lean{MeasureTheory.Martingale.congr}
If $X$ is a martingale and $Y$ is an adapted modification of $X$, then $Y$ is a martingale.
\end{lemma}

n16615.content:
\begin{lemma}\label{lem:Submartingale.congr}
  \uses{def:Submartingale, def:adapted}
  \leanok
  \lean{MeasureTheory.Submartingale.congr}
If $X$ is a submartingale and $Y$ is an adapted modification of $X$, then $Y$ is a submartingale.
\end{lemma}

n16617.content:
\begin{lemma}[Jensen's inequality for the conditional expectation]\label{lem:conditional_jensen}
  \mathlibok
  \lean{ConvexOn.map_condExp_le_univ}
Let $X : \Omega \to E$ be an integrable random variable with values in a normed space $E$ and let $\phi : E \to \mathbb{R}$ be a convex function such that $\phi \circ X$ is integrable.
Then, for any sub-$\sigma$-algebra $\mathcal{G}$, we have
\begin{align*}
  \phi\left( \mathbb{E}[X \mid \mathcal{G}] \right)
  &\le \mathbb{E}[\phi(X) \mid \mathcal{G}] \quad \text{a.s.}
\end{align*}
\end{lemma}

n16618.content:
\begin{proof}\leanok
Done in a Mathlib PR for finite measures: \href{https://github.com/leanprover-community/mathlib4/pull/27953}{\#27953}.
\end{proof}

n16619.content:
\begin{corollary}\label{cor:norm_condExp_le}
  \leanok
  \lean{MeasureTheory.norm_condExp_le}
Let $X : \Omega \to E$ be an integrable random variable with values in a normed space $E$.
Then, for any sub-$\sigma$-algebra $\mathcal{G}$, we have
\begin{align*}
  \Vert \mathbb{E}[X \mid \mathcal{G}] \Vert
  &\le \mathbb{E}[\Vert X \Vert \mid \mathcal{G}] \quad \text{a.s.}
\end{align*}
\end{corollary}

n16621.content:
\begin{lemma}\label{lem:Martingale.submartingale_convex_comp}
  \uses{def:Martingale, def:Submartingale}
  \leanok
  \lean{MeasureTheory.Martingale.submartingale_convex_comp}
Let $X : T \rightarrow \Omega\rightarrow E$ a martingale with values in a normed space $E$.
Let $\phi : E \rightarrow \mathbb{R}$ convex and continuous such that
$\phi(X_t)\in L^1(\Omega)$ for every $t\in T$. Then $\phi(X)$ is a sub-martingale.
\end{lemma}

n16622.content:
\begin{proof}
  \uses{lem:conditional_jensen}
  \leanok
  % See 1.4.12 Pascucci
  By the conditional Jensen inequality (Lemma~\ref{lem:conditional_jensen}),
  $\phi(X_t) = \phi\left( \mathbb{E}[X_T\ |\ \mathcal{F}_t] \right)\leq \mathbb{E}[\phi(X_T)\ |\ \mathcal{F}_t]$.
\end{proof}

n16623.content:
\begin{corollary}\label{cor:Martingale.submartingale_norm}
  \uses{def:Martingale, def:Submartingale}
  \leanok
  \lean{MeasureTheory.Martingale.submartingale_norm}
  Let $X : T \rightarrow \Omega \rightarrow E$ a martingale with values in a normed space $E$.
  Then $\Vert X \Vert$ is a sub-martingale.
\end{corollary}

n16624.content:
\begin{proof}
  \uses{cor:norm_condExp_le}
  \leanok
Same proof as Lemma~\ref{lem:Martingale.submartingale_convex_comp}, specialized to $\phi = \Vert \cdot \Vert$, for which we can use Corollary~\ref{cor:norm_condExp_le}.
\end{proof}

n16625.content:
\begin{lemma}\label{lem:convex_of_submg_is_submg}
  \uses{def:Submartingale}
  \leanok
  \lean{MeasureTheory.Submartingale.monotone_convex_comp}
Let $X : T  \rightarrow \Omega \rightarrow E$ a sub-martingale.
Let $\phi:E \rightarrow \mathbb{R}$ convex, continuous, and increasing such that
$\phi(X_t)\in L^1(\Omega)$ for every $t\in T$. Then $\phi(X)$ is a sub-martingale.
\end{lemma}

n16626.content:
\begin{proof}
  \leanok
  By Jensen and the fact that $\phi$ is increasing
  $\phi(X_t) \leq \phi\left( \mathbb{E}[X_T\ |\ \mathcal{F}_t] \right)\leq \mathbb{E}[\phi(X_T)\ |\ \mathcal{F}_t]$.
\end{proof}

n16627.content:
\begin{definition}[Stopping time]\label{def:IsStoppingTime}
  \uses{def:filtration}
  \mathlibok
  \lean{MeasureTheory.IsStoppingTime}
A stopping time with respect to some filtration $\mathcal{F}$ indexed by $T$ is a function $\tau : \Omega \to T \cup \{\infty\}$ such that for all $i$, the preimage of $\{j \mid j \le i\}$ along $\tau$ is measurable with respect to $\mathcal{F}_i$.
\end{definition}

n16628.content:
\begin{definition}[$\sigma$-algebra generated by a stopping time]\label{def:StoppingTimeGen}
  \uses{def:IsStoppingTime, def:filtration}
  \mathlibok
  \lean{MeasureTheory.IsStoppingTime.measurableSpace}
  Given a stopping time $\tau$ on a time index $T$, define
  $\mathcal{F}_\tau = \bigcap_{t \in T} \{A \in \mathcal{F} \mid A \cap \{\tau \le t\} \in \mathcal{F}_t\}.$
\end{definition}

n16629.content:
\begin{lemma}\label{lem:StoppingTimeGenMono}
  \uses{def:StoppingTimeGen}
  \mathlibok
  \lean{MeasureTheory.IsStoppingTime.measurableSpace_mono}
  Let $\tau, \sigma$ be stopping times such that $\tau \le \sigma$.
  Then, $\mathcal{F}_\tau \subseteq \mathcal{F}_\sigma$.
\end{lemma}

n16631.content:
\begin{definition}[Stopped process]\label{def:stoppedProcess}
  \mathlibok
  \lean{MeasureTheory.stoppedProcess}
Let $X : T \to \Omega \to E$ be a stochastic process and let $\tau : \Omega \to T$.
The stopped process with respect to $\tau$ is defined by
\begin{align*}
  (X^{\tau})_t = \begin{cases}
    X_t & \text{if } t \le \tau \\
    X_{\tau} & \text{otherwise}
  \end{cases}
\end{align*}
\end{definition}

n16632.content:
\begin{lemma}\label{lem:Submartingale.stoppedProcess}
  \uses{def:Submartingale, def:stoppedProcess}
  \mathlibok
  \lean{MeasureTheory.Submartingale.stoppedProcess}
Let $X : \mathbb{N} \to \Omega \to \mathbb{R}$ be a sub-martingale and $\tau$ a stopping time with respect to the filtration $\mathcal{F}$.
Then, the stopped process $X^{\tau}$ is a sub-martingale with respect to the filtration $\mathcal{F}$.
\end{lemma}

n16634.content:
\begin{definition}[Hitting time]\label{def:hittingAfter}
  \mathlibok
  \lean{MeasureTheory.hittingAfter}
For $X : T \to \Omega \to E$ a stochastic process, $B$ a subset of $E$ and $t_0 \in T$, the hitting time of $X$ in $B$ after $t_0$ is the random variable $\Omega \to T\cup\{\infty\}$ defined by
\begin{align*}
  \tau_{B, t_0}(\omega) = \inf\{t \in T \mid t \ge t_0, \: X_t(\omega) \in B\} \: ,
\end{align*}
in which the infimum is infinite if the set is empty.
\end{definition}

n16635.content:
\begin{definition}\label{def:hittingBtwn}
  \mathlibok
  \lean{MeasureTheory.hittingBtwn}
For $X : T \to \Omega \to E$ a stochastic process, $B$ a subset of $E$ and $t_0, t_1 \in T$, the hitting time of $X$ in $B$ between $t_0$ and $t_1$ is the random variable $\Omega \to T\cup\{\infty\}$ defined by
\begin{align*}
  \tau_{B, t_0, t_1}(\omega) = \inf\{t \in T \mid t_0 \le t \le t_1, \: X_t(\omega) \in B\} \: ,
\end{align*}
in which the infimum is infinite if the set is empty.
\end{definition}

