\begin{definition}[Ring of sets]\label{def:ringOfSets}
  \mathlibok
  \lean{MeasureTheory.IsSetRing}
  A \emph{ring of sets} $C$ is a family of sets containing $\emptyset$,
  stable by union and set difference (and thus also by intersection).
\end{definition}

