n17089.content:
\begin{lemma}\label{lem:submartingale_iff_integral_elemStochIntegral_nonneg}
  \uses{def:elemStochIntegral, def:Submartingale, def:limitProcess}
An adapted integrable process $X$ is a submartingale if and only if for every bounded simple process $V$ with values in $\mathbb{R}_+$, $\mathbb{E}[(V \bullet_{\mathbb{R}} X)_\infty] \ge 0$.

Note that in Lean $V$ comes with the data of a sum representation: by ``values in $\mathbb{R}_+$'' we mean that the random variables in that particular sum representing $V$ are nonnegative.
\end{lemma}

n17091.content:
\begin{lemma}\label{lem:martingale_iff_integral_elemStochIntegral_eq_zero}
  \uses{def:elemStochIntegral, def:Martingale}
An adapted integrable process $X$ is a martingale if and only if for every bounded simple process $V$ with values in $\mathbb{R}$, $\mathbb{E}[(V \bullet_{\mathbb{R}} X)_\infty] = 0$.
\end{lemma}

n17092.content:
\begin{proof}
  \uses{lem:tendsto_elemStochIntegral_limitProcess, def:Martingale}
There might not be an order on the type $E$ of values of $X$, so we cannot just say that $X$ is a martingale if and only if both $X$ and $-X$ are submartingales and conclude with Lemma~\ref{lem:submartingale_iff_integral_elemStochIntegral_nonneg}.
But we can use almost the same proof as in Lemma~\ref{lem:submartingale_iff_integral_elemStochIntegral_nonneg}, replacing inequalities by equalities?
\end{proof}

n17093.content:
\begin{corollary}\label{cor:Submartingale.integral_elemStochIntegral_le}
  \uses{def:elemStochIntegral, def:Submartingale}
Let $X$ be a submartingale and $A$ be an elementary predictable set.
Then for all $t \in T$,
\begin{align*}
  \mathbb{E}[(\mathbb{1}_A \bullet_{\mathbb{R}} X)_t] \le \mathbb{E}[X_t - X_0]
  \: .
\end{align*}
\end{corollary}

n17094.content:
\begin{proof}
  \uses{lem:submartingale_iff_integral_elemStochIntegral_nonneg}
Let $A$ be an elementary predictable set and let $t \in T$.
\begin{align*}
  \mathbb{E}[(\mathbb{1}_A \bullet_{\mathbb{R}} X)_t]
  &= \mathbb{E}[X_t - X_0] - \mathbb{E}[(\mathbb{1}_{A^c} \bullet_{\mathbb{R}} X)_t]
  \le \mathbb{E}[X_t - X_0]
  \: .
\end{align*}
The inequality follows from Lemma~\ref{lem:submartingale_iff_integral_elemStochIntegral_nonneg} applied to the nonnegative bounded simple process $\mathbb{1}_{A^c}$.
\end{proof}

n17095.content:
\begin{lemma}\label{lem:Submartingale.elemStochIntegral}
  \uses{def:elemStochIntegral, def:Submartingale}
Let $X$ be a submartingale and $V$ be a nonnegative bounded simple process.
Then the elementary stochastic integral $V \bullet_{\mathbb{R}} X$ is a submartingale.
\end{lemma}

n17096.content:
\begin{proof}
  \uses{lem:submartingale_iff_integral_elemStochIntegral_nonneg, lem:elemStochIntegral_assoc}
We use Lemma~\ref{lem:submartingale_iff_integral_elemStochIntegral_nonneg} and have to show that for every nonnegative bounded simple process $W$, $\mathbb{E}[(W \bullet_{\mathbb{R}} (V \bullet_{\mathbb{R}} X))_\infty] \ge 0$.
By Lemma~\ref{lem:elemStochIntegral_assoc}, this is $\mathbb{E}[((W \times V) \bullet_{\mathbb{R}} X)_\infty]$.
Since $W \times V$ is a nonnegative bounded simple process, this is nonnegative by Lemma~\ref{lem:submartingale_iff_integral_elemStochIntegral_nonneg} applied to $X$.
\end{proof}

n17097.content:
\begin{lemma}\label{lem:Martingale.elemStochIntegral}
  \uses{def:elemStochIntegral, def:Martingale}
Let $X$ be a martingale and $V$ be a bounded simple process.
Then the elementary stochastic integral $V \bullet_B X$ is a martingale.
\end{lemma}

n17098.content:
\begin{proof}
  \uses{lem:martingale_iff_integral_elemStochIntegral_eq_zero, cor:elemStochIntegral_assoc_real_bilin}
We use Lemma~\ref{lem:martingale_iff_integral_elemStochIntegral_eq_zero} and have to show that for every bounded simple process $W$, $\mathbb{E}[(W \bullet_{\mathbb{R}} (V \bullet_B X))_\infty] = 0$.
By Lemma~\ref{cor:elemStochIntegral_assoc_real_bilin}, this is $\mathbb{E}[((W \bullet_{\mathbb{R}} V) \bullet_B X)_\infty]$.
Since $W \bullet_{\mathbb{R}} V$ is a bounded simple process, this is zero by Lemma~\ref{lem:martingale_iff_integral_elemStochIntegral_eq_zero} applied to $X$.
\end{proof}

n17099.content:
\begin{definition}[Stochastic intervals]\label{def:stochasticInterval}
  \leanok
  \lean{ProbabilityTheory.stochIcc, ProbabilityTheory.stochIco, ProbabilityTheory.stochIoc, ProbabilityTheory.stochIoo, ProbabilityTheory.stochGraph}
Let $T$ be a time domain and let $\sigma, \tau$ be functions $\Omega \to T \cup \{\infty\}$.
We define
\begin{align*}
  [\![\sigma, \tau]\!]
  &= \{(t, \omega) \in T \times \Omega \mid \sigma(\omega) \le t \le \tau(\omega)\}
  \:, \\
  [\![\sigma, \tau[\![
  &= \{(t, \omega) \in T \times \Omega \mid \sigma(\omega) \le t < \tau(\omega)\}
  \:, \\
  ]\!]\sigma, \tau]\!]
  &= \{(t, \omega) \in T \times \Omega \mid \sigma(\omega) < t \le \tau(\omega)\}
  \:, \\
  ]\!]\sigma, \tau[\![
  &= \{(t, \omega) \in T \times \Omega \mid \sigma(\omega) < t < \tau(\omega)\}
  \:, \\
  [\![\sigma]\!]
  &= \{(t, \omega) \in T \times \Omega \mid \sigma(\omega) = t\} = [\![\sigma, \sigma]\!]
  \:.
\end{align*}
We call those stochastic intervals. Note that these are subsets of $T \times \Omega$, not of $ (T \cup \{\infty\}) \times \Omega$.
$[\![\sigma]\!]$ is called the graph of $\sigma$.
\end{definition}

n17100.content:
\begin{lemma}\label{lem:predictable_stochasticInterval}
  \uses{def:IsStoppingTime, def:stochasticInterval, def:predictable}
If $\sigma$ and $\tau$ are stopping times, then the stochastic interval $]\!]\sigma, \tau]\!]$ is a predictable set.
\end{lemma}

n17102.content:
\begin{lemma}\label{lem:elementaryPredictableSet_stochasticInterval}
  \uses{def:stochasticInterval, def:elementaryPredictableSet, def:IsStoppingTime}
  \leanok
  \lean{ProbabilityTheory.stochIoc.exists_elementaryPredictableSet}
If $\sigma$ and $\tau$ are stopping times on $\mathbb{N}$, with $\tau$ bounded, then the stochastic interval $]\!]\sigma, \tau]\!]$ is an elementary predictable set.
\end{lemma}

n17103.content:
\begin{proof}\leanok
Let $n$ be an upper bound for $\tau$.
To see that the stochastic interval is an elementary predictable set, note that it can be written as a finite disjoint union of sets
\begin{align*}
  \{\sigma(\omega) < t \le \tau(\omega)\}
  &= \bigcup_{k=1}^{n} \{k\} \times \{\sigma < k \le \tau\}
  \\ &= \bigcup_{k=1}^{n} (k-1, k] \times \{\sigma \le k-1 < \tau\}
\end{align*}
where $\{\sigma \le k-1 < \tau\} \in \mathcal{F}_{k-1}$.
Therefore this is an elementary predictable set.
\end{proof}

n17104.content:
\begin{definition}\label{def:lowerCrossingTimeAux}
  \uses{def:hittingBtwn}
  \mathlibok
  \lean{MeasureTheory.lowerCrossingTimeAux}
Let $X : T \to \Omega \to \mathbb{R}$ be a stochastic process, $t \in T$, and $a, b \in \mathbb{R}$.
The auxiliary lower crossing time $\sigma'_{a, s, t}$ is the hitting time of the set $(-\infty, a]$ by the process $X$ between times $s$ and $t$.
\end{definition}

n17105.content:
\begin{definition}[Upper crossing time]\label{def:upperCrossingTime}
  \uses{def:lowerCrossingTimeAux}
  \mathlibok
  \lean{MeasureTheory.upperCrossingTime}
Let $X : T \to \Omega \to \mathbb{R}$ be a stochastic process, $t \in T$, and $a, b \in \mathbb{R}$.
The $n$-th upper crossing time $\tau^n_{a, b, t}$ of the interval $[a, b]$ by $X$ before time $t$ is the hitting time of the set $[b, \infty)$ by $X$ after hitting the set $(-\infty, a]$ for the $n-1$-th time.

That is, $\tau^0_{a, b, t} = 0$, and for all $n$, $\tau^{n+1}_{a, b, t}$ is the hitting time of $[b, \infty)$ by $X$ between $\sigma'_{a, \tau^{n}_{a, b, t}, t}$ and $t$.
\end{definition}

n17106.content:
\begin{definition}[Lower crossing time]\label{def:lowerCrossingTime}
  \uses{def:upperCrossingTime}
  \mathlibok
  \lean{MeasureTheory.lowerCrossingTime}
Let $X : T \to \Omega \to \mathbb{R}$ be a stochastic process, $t \in T$, and $a, b \in \mathbb{R}$.
The $n$-th lower crossing time $\sigma^n_{a, b, t}$ of the interval $[a, b]$ by $X$ before time $t$ is the hitting time of the set $(-\infty, a]$ by $X$ after hitting the set $[b, \infty)$ for the $n$-th time.

That is, it is the hitting time of $(-\infty, a]$ by $X$ between $\tau^n_{a, b, t}$ and $t$.
\end{definition}

n17107.content:
\begin{definition}[Upcrossings before time $t$]\label{def:upcrossingsBefore}
  \uses{def:upperCrossingTime}
  \mathlibok
  \lean{MeasureTheory.upcrossingsBefore}
Let $X : T \to \Omega \to \mathbb{R}$ be a stochastic process, $t \in T$, and $a, b \in \mathbb{R}$.
The number of upcrossings $U_t[a, b]$ of the interval $[a, b]$ by $X$ before time $t$ is the largest $n$ such that $\tau^n_{a, b, t} < t$, or $\infty$ if there is no such largest $n$.
\end{definition}

n17108.content:
\begin{definition}[Upcrossings]\label{def:upcrossings}
  \uses{def:upcrossingsBefore}
  \mathlibok
  \lean{MeasureTheory.upcrossings}
Let $X : T \to \Omega \to \mathbb{R}$ be a stochastic process and $a, b \in \mathbb{R}$.
The number of upcrossings $U[a, b]$ of the interval $[a, b]$ by $X$ is the supremum over $t \in T$ of the number of upcrossings $U_t[a, b]$ of $[a, b]$ by $X$ before time $t$.
\end{definition}

n17109.content:
\begin{lemma}\label{lem:tendsto_of_no_upcrossings}
  \uses{def:upcrossings}
  \mathlibok
  \lean{tendsto_of_no_upcrossings}
Let $u : \beta \to \alpha$, for $\alpha$ a densely ordered, conditionally complete linear order equipped with the order topology.
Let $S$ be a dense subset of $\alpha$ and $f$ a filter of $\beta$.
If for all $a < b$ in $S$, the number of upcrossings of the interval $[a, b]$ by $u$ along $f$ is finite, then $u$ tends to a limit along $f$.
\end{lemma}

