\begin{lemma}\label{lem:predictable_upcrossingPredictableSet}
  \uses{def:upcrossingPredictableSet, def:predictable}
The upcrossing predictable set $A_N$ of $X : \mathbb{N} \to \Omega \to \mathbb{R}$ before time $N$ is a predictable set.
\end{lemma}

n17117.content:
\begin{proof}
  \uses{lem:isStoppingTime_lowerCrossingTime, lem:isStoppingTime_upperCrossingTime, lem:predictable_stochasticInterval}
By Lemmas \ref{lem:isStoppingTime_lowerCrossingTime} and \ref{lem:isStoppingTime_upperCrossingTime}, $\sigma^k_{a, b, N}$ and $\tau^{k+1}_{a, b, N}$ are stopping times.
Hence by Lemma~\ref{lem:predictable_stochasticInterval}, the stochastic interval $]\!]\sigma^k_{a, b, N}, \tau^{k+1}_{a, b, N}]\!]$ is a predictable set for each $k$.
Since a finite union of predictable sets is predictable, $A_N$ is predictable.
\end{proof}

