  \uses{def:upcrossingPredictableSet, def:elementaryPredictableSet}
The upcrossing predictable set $A_N$ of $X : \mathbb{N} \to \Omega \to \mathbb{R}$ before time $N$ is an elementary predictable set.
\end{lemma}

n17119.content:
\begin{proof}
  \uses{lem:isStoppingTime_lowerCrossingTime, lem:isStoppingTime_upperCrossingTime, lem:elementaryPredictableSet_stochasticInterval}
By Lemmas \ref{lem:isStoppingTime_lowerCrossingTime} and \ref{lem:isStoppingTime_upperCrossingTime}, $\sigma^k_{a, b, N}$ and $\tau^{k+1}_{a, b, N}$ are stopping times, and are bounded by $N$.
By Lemma~\ref{lem:elementaryPredictableSet_stochasticInterval}, the stochastic intervals $]\!]\sigma^k_{a, b, N}, \tau^{k+1}_{a, b, N}]\!]$ are elementary predictable sets for each $k$.
Since a finite union of elementary predictable sets is elementary predictable, $A_N$ is elementary predictable.
\end{proof}

n17120.content:
\begin{lemma}\label{lem:upcrossing_simpleProcess_le_nat}
  \uses{def:elemStochIntegral, def:simpleProcess, def:upcrossings, def:upcrossingPredictableSet}
Let $X : \mathbb{N} \to \Omega \to \mathbb{R}$ be an adapted process on the natural numbers.
Then for all $a < b$ in $\mathbb{R}$ and $t \in \mathbb{N}$, for $A_t$ the upcrossing predictable set of $X$ before time $t$, the number of upcrossings $U_t[a, b]$ of the interval $[a, b]$ before time $t$ satisfies
\begin{align*}
  (b - a) U_t[a, b] \le (\mathbb{1}_{A_t} \bullet X)_t + \max\{a - X_t, 0\}
  \:.
\end{align*}
\end{lemma}

n17121.content:
\begin{proof}
  \uses{lem:elementaryPredictableSet_upcrossingPredictableSet}
\begin{align*}
  (\mathbb{1}_{A_t} \bullet X)_t
  &= \sum_{k=0}^t (X_{\tau^{k+1}_{a, b, t} \wedge t} - X_{\sigma^k_{a, b, t} \wedge t})
  \\
  &= \sum_{k=0}^{U_t[a, b]-1} (X_{\tau^{k+1}_{a, b, t} \wedge t} - X_{\sigma^k_{a, b, t} \wedge t})
    + (X_t - X_{\sigma^{U_t[a, b]}_{a, b, t} \wedge t})
  \\
  &\ge (b - a) U_t[a, b] + \min\{X_t - a, 0\}
  \\
  &= (b - a) U_t[a, b] - \max\{a - X_t, 0\}
  \: .
\end{align*}
\end{proof}

