n17396.content:
\begin{lemma}\label{lem:monotone_quadraticVariation}
  \uses{def:quadraticVariation}
  \leanok
  \lean{ProbabilityTheory.monotone_predQuadVariation}
The predictable quadratic variation $\langle M \rangle$ of $M \in \mathcal{M}^2_{\mathrm{loc}}$ is non-decreasing.
\end{lemma}

n17398.content:
\begin{lemma}\label{lem:local_martingale_sub_quadraticVariation}
  \uses{def:quadraticVariation}
For $M \in \mathcal{M}^2_{\mathrm{loc}}$, the process $\Vert M_t \Vert^2 - \langle M \rangle_t$ is a local martingale.
\end{lemma}

n17400.content:
\begin{definition}[Predictable covariation]\label{def:covariation}
  \uses{def:IsLocallySquareIntegrable, def:quadraticVariation}
  \leanok
  \lean{ProbabilityTheory.predQuadCovariation}
For $M, N \in \mathcal{M}^2_{\mathrm{loc}}$, the predictable covariation $\langle M, N \rangle$ is a stochastic process defined by polarization of the predictable quadratic variation:
\begin{align*}
  \langle M, N \rangle_t = \frac{1}{2}\left(\langle M+N \rangle_t - \langle M \rangle_t - \langle N \rangle_t \right)
  \: .
\end{align*}
\end{definition}

n17401.content:
\begin{lemma}\label{lem:predictable_covariation}
  \uses{def:covariation}
  \leanok
  \lean{ProbabilityTheory.isStronglyPredictable_predQuadCovariation}
The predictable covariation $\langle M, N \rangle$ of $M, N \in \mathcal{M}^2_{\mathrm{loc}}$ is a predictable process.
\end{lemma}

n17403.content:
\begin{lemma}\label{lem:cadlag_covariation}
  \uses{def:covariation}
  \leanok
  \lean{ProbabilityTheory.isCadlag_predQuadCovariation}
The predictable covariation $\langle M, N \rangle$ of $M, N \in \mathcal{M}^2_{\mathrm{loc}}$ is càdlàg.
\end{lemma}

n17407.content:
\begin{lemma}\label{lem:local_martingale_sub_covariation}
  \uses{def:covariation}
For $M, N \in \mathcal{M}^2_{\mathrm{loc}}$, the process $\langle M_t, N_t \rangle_E - \langle M, N \rangle_t$ is a local martingale.
\end{lemma}

n17408.content:
\begin{proof}
  \uses{lem:local_martingale_sub_quadraticVariation}
\begin{align*}
  &\langle M_t, N_t \rangle_E - \langle M, N \rangle_t
  \\
  &= \frac{1}{4}\left( \left(\Vert M_t + N_t \Vert^2 - \langle M+N \rangle_t\right) - \left(\Vert M_t - N_t \Vert^2 - \langle M-N \rangle_t\right) \right)
  \: .
\end{align*}
The two differences are local martingales by Lemma~\ref{lem:local_martingale_sub_quadraticVariation}, so their linear combination is also a local martingale.
\end{proof}

n17409.content:
\begin{lemma}\label{lem:covariation_eq_inner}
  \uses{def:covariation, def:IsSquareIntegrable}
Let $M$ and $N$ be square integrable martingales. Then
\begin{align*}
  \mathbb{E}\left[\langle M,N \rangle_\infty\right] = \langle M - M_0, N - N_0 \rangle_{\mathcal{M}^2}
  \: .
\end{align*}
\end{lemma}

n17411.content:
\begin{lemma}\label{lem:quadraticVariation_brownian}
  \uses{def:brownian, def:quadraticVariation}
Let $B$ be a standard Brownian motion. Then the quadratic variation of $B$ is given by $\langle B \rangle_t = t$~.
\end{lemma}

n17413.content:
\begin{lemma}\label{lem:IsLocalMartingale.locally_hasIntegrableVariation_largeJumps}
  \uses{def:IsLocalMartingale, def:HasIntegrableVariation, def:largeJump}
The large jump process of a local martingale is a process with locally integrable variation (it's in $(\mathcal{A} \cap \mathcal{M})_{\mathrm{loc}}$).
\end{lemma}

n17415.content:
\begin{theorem}\label{thm:local_martingale_decomposition}
  \uses{def:IsLocalMartingale}
Let $M$ be a local martingale.
Then for any $\varepsilon > 0$, $M$ can be decomposed as $M = M_0 + U + V$, where $U$ is a locally bounded martingale (local version of both bounded and martingale) with $\vert \Delta U \vert \le \varepsilon$ and $U_0 = 0$ and $V$ is a local martingale with locally integrable variation ($V \in (\mathcal{M} \cap \mathcal{A})_{\mathrm{loc}}$) and $V_0 = 0$.
\end{theorem}

n17417.content:
\begin{definition}[Semimartingale]\label{def:IsSemimartingale}
  \uses{def:IsLocalMartingale, def:HasFiniteVariation, def:adapted}
A process $X$ is a semimartingale if it can be decomposed as $X = M + A$, where $M$ is a local martingale ($M \in \mathcal{M}_{\mathrm{loc}}$) and $A$ is an adapted process with finite variation.
\end{definition}

n17418.content:
\begin{lemma}\label{lem:IsSemimartingale.decomposition}
  \uses{def:IsSemimartingale}
A semimartingale $X$ can be decomposed as $X = M + A$, where $M$ is a locally bounded martingale with bounded jumps and $A$ is an adapted process with finite variation.
\end{lemma}

n17419.content:
\begin{proof}
  \uses{thm:local_martingale_decomposition}
Decompose $X = M + A$ as in Definition~\ref{def:IsSemimartingale}.
Then decompose $M$ as in Theorem~\ref{thm:local_martingale_decomposition} with $\varepsilon = 1$.
Then $M = M_0 + U + V$ with $U$ a locally bounded martingale with $\vert \Delta U \vert \le 1$ and $V$ a local martingale with locally integrable variation.
Then $X = (M_0 + U) + (A + V)$, with $U$ a locally bounded martingale with bounded jumps and $A + V$ an adapted process of finite variation (since $V$ has locally integrable variation, hence finite variation).
\end{proof}

n17421.content:
\begin{definition}[Quadratic covariation of semimartingales]\label{def:quadCovariation}
  \uses{def:IsSemimartingale, def:quadraticVariation, def:IsSemimartingale.continuousMartingalePart}
Let $X$ and $Y$ be semimartingales. Their quadratic covariation $[X, Y]$ is defined as
\begin{align*}
  [X, Y]_t = X_0 Y_0 + \langle X^c, Y^c \rangle_t + \sum_{0 < s \le t} \Delta X_s \Delta Y_s
  \: .
\end{align*}
\end{definition}

n17422.content:
\begin{definition}[Quadratic variation of a semimartingale]\label{def:quadVariation}
  \uses{def:quadCovariation}
The quadratic variation of a semimartingale $X$ is defined as $[X] = [X, X]$~.
\end{definition}

n17423.content:
\begin{definition}[Special semimartingale]\label{def:IsSpecialSemimartingale}
  \uses{def:IsSemimartingale, def:HasIntegrableVariation}
A semimartingale $X$ is a special semimartingale if it can be decomposed as $X = M + A$, where $M$ is a local martingale and $A$ is an adapted process with locally integrable variation.
\end{definition}

n17424.content:
\begin{theorem}\label{lem:IsSpecialSemimartingale.decomposition}
  \uses{def:IsSpecialSemimartingale}
A special semimartingale $X$ can be decomposed as $X = M + A$, where $M$ is a local martingale and $A$ is a predictable process with finite variation and $A_0 = 0$.
\end{theorem}

n17426.content:
\begin{definition}[Additive content]\label{def:addContent}
  \mathlibok
  \lean{MeasureTheory.AddContent}
  Let $E$ be a commutative monoid and $\mathcal{A}$ be a family of sets.
  An \emph{additive content} is a set function $\lambda : \mathcal{A} \to E$
  with value $0$ at the empty set
  which is finitely additive on $\mathcal{A}$~.
\end{definition}

n17427.content:
\begin{lemma}\label{lem:addContent_extension}
  \uses{def:addContent, def:semiRingOfSets, def:ringOfSets}
  \mathlibok
  \lean{MeasureTheory.sum_addContent_eq_of_sUnion_eq}
  Let $\lambda$ be an additive content on a semi-ring of sets $C$~.
  Then $\lambda$ admits a unique additive extension to the ring of sets generated by $C$~.
\end{lemma}

n17429.content:
\begin{definition}[Content associated with a process]\label{def:contentAssociatedWithProcess}
  \uses{
  def:addContent,
  def:predictableRectangles,
  lem:predictableRectangles_isSetSemiring,
  def:elementaryPredictableSet,
  lem:elementaryPredictableSets_isSetRing_of,
  lem:addContent_extension
  }
Let $X : T \to \Omega \to E$, where $E$ is a Banach space,
 be an adapted process with $X_t \in L^1$ for every $t \in T$~.
The \emph{content} $\lambda_X$ associated with $X$
is an $E$-valued additive content on
elementary predictable sets,
given on predictable rectangles by
\begin{align*}
  \lambda_X((s, t] \times F) &= \mathbb{E}[\mathbb{1}_F (X_t - X_s)],
  & s < t \text{ in } T,\ F \in \mathcal{F}_s,
  \\
  \lambda_X(\{0\} \times F) &= 0,
  & F \in \mathcal{F}_0
  \: .
\end{align*}
\end{definition}

n17430.content:
\begin{lemma}\label{lem:contentAssociatedWithProcess_wellDefined}
  \uses{def:contentAssociatedWithProcess}
  The content $\lambda_X$ associated with $X$ is uniquely defined.
\end{lemma}

n17431.content:
\begin{proof}
  \uses{lem:addContent_extension, lem:predictableRectangles_isSetSemiring, lem:elementaryPredictableSets_isSetRing_of}
The uniqueness of $\lambda_X$ is guaranteed by Lemma~\ref{lem:addContent_extension},
since the predictable rectangles form a semi-ring of sets
(Lemma~\ref{lem:predictableRectangles_isSetSemiring}),
one that generates the ring of elementary predictable sets
(Lemma~\ref{lem:elementaryPredictableSets_isSetRing_of}).
\end{proof}

n17432.content:
\begin{definition}[Partition of a set]\label{def:partitionOfSet}
  \mathlibok
  \lean{IndexedPartition}
  An \emph{partition} of a set $A$ is a family of pairwise disjoint sets,
  which does not contain the empty set, and whose union is $A$~.
  For a family of sets $C$, a \emph{$C$-partition} of $A$ is a partition of $A$ consisting of sets in $C$~.
\end{definition}

n17433.content:
\begin{definition}[Bounded variation of a content]\label{def:contentBoundedVariation}
  \uses{def:ringOfSets, def:addContent, def:partitionOfSet}
An additive content $\lambda$ on a ring $\mathcal{A}$ of sets, with values in a normed space $E$,
has \emph{bounded variation} on a set $A \in \mathcal{A}$ if
\begin{align*}
  \vert \lambda \vert(A)
  := \sup
  \Big\{
    \sum_{i=1}^n \| \lambda(A_i) \|
    \:\Big|\:
    (A_i)_{i=1}^n \text{ finite } \mathcal{A}\text{-partition of } A
  \Big\}
  < \infty
  \: .
\end{align*}
\end{definition}

n17434.content:
\begin{lemma}\label{lem:contentBoundedVariation_equivOnGenerator}
  \uses{def:contentBoundedVariation}
  We can equivalently take supremum over $C$-partitions of $A$ in the above
  definition, when $\mathcal{A}$ is generated by the semi-ring $C$~.
\end{lemma}

n17435.content:
\begin{proof}
  \uses{
    def:partitionOfSet,
    lem:setRing_of_finiteUnions,
    lem:semiRingOfSets_disjoint_of_union,
    def:contentBoundedVariation
  }
  This follows (by triangle inequality and additivity of the content)
  from the Definition~\ref{def:partitionOfSet},
  and from the Lemmata~\ref{lem:semiRingOfSets_disjoint_of_union},
  \ref{lem:setRing_of_finiteUnions}.
\end{proof}

n17436.content:
\begin{lemma}\label{lem:contentEquivElementaryIntegral}
  \uses{def:contentAssociatedWithProcess, def:elementaryPredictableSet, def:elemStochIntegralBilin}
  The content $\lambda_X$ associated with a process $X$ satisfies,
  for every elementary predictable set $A\subseteq (0, t] \times \Omega$,
\begin{align*}
  \lambda_X(A) = \mathbb{E}[(\mathbb{1}_A \bullet X)_t]
  \: .
\end{align*}
\end{lemma}

n17438.content:
\begin{definition}[Quasi-martingale]\label{def:Quasimartingale}
  \uses{def:contentAssociatedWithProcess, def:contentBoundedVariation}
Let $E$ be a Banach space.
An adapted integrable process $X : T \to \Omega \to E$ is called a
\emph{quasi-martingale} if the additive content $\lambda_X$ (on elementary predictable sets)
associated with $X$ has bounded variation on every set $(0, t] \times \Omega$ with $t \in T$~, that is,
\begin{align*}
  \forall t \in T, \quad \vert \lambda_X \vert\big((0, t] \times \Omega\big) < \infty
  \: .
\end{align*}
\end{definition}

n17441.content:
\begin{definition}\label{def:StieltjesFunction.measure}
  \mathlibok
  \lean{StieltjesFunction.measure}
Let $f : T \to \mathbb{R}$ be a right-continuous monotone function on a conditionally complete linear order $T$.
We denote by $d_+ f$ the measure on $T$ defined by $d_+ f((a, b]) = f(b) - f(a)$ for all $a, b \in T$~.
\end{definition}

n17442.content:
\begin{lemma}\label{lem:StieltjesFunction.measurable_measure}
  \uses{def:StieltjesFunction.measure}
Let $X : T \to \Omega \to \mathbb{R}$ be a right-continuous adapted process which is monotone in the time variable.
Then the measure $d_+ X_\omega$ is measurable in $\omega$~.
\end{lemma}

n17444.content:
\begin{definition}\label{def:BoundedVariationOn.vectorMeasure}
  \uses{def:BoundedVariationOn}
  \mathlibok
  %\lean{BoundedVariationOn.vectorMeasure}
Let $f : T \to E$ be a function of bounded variation on a suitable order $T$, with $E$ a complete normed additive group.
Then there exists a signed measure $df$ on $T$ defined by $df((a, b]) = f(b^+) - f(a^+)$~.
\end{definition}

n17445.content:
\begin{lemma}\label{lem:BoundedVariationOn.measurable_vectorMeasure}
  \uses{def:BoundedVariationOn.vectorMeasure}
Let $X : T \to \Omega \to E$ be an adapted process which is of bounded variation in the time variable.
Then the measure $dX_\omega$ is measurable in $\omega$~.
\end{lemma}

n17447.content:
\begin{lemma}\label{lem:eVariationOn_eq_totalVariation}
  \uses{def:BoundedVariationOn.vectorMeasure, def:eVariationOn}
Denoting by $\vert df \vert$ the total variation of the measure $df$~,
$V_f([a, b]) = \vert df \vert([a, b])$~.
\end{lemma}

n17449.content:
\begin{lemma}\label{lem:BoundedVariationOn.vectorMeasure_of_monotone}
  \uses{def:BoundedVariationOn.vectorMeasure, def:StieltjesFunction.measure}
If $f : T \to \mathbb{R}$ is a right-continuous monotone function, then the measure $df$ coincides with the measure $d_+ f$~.
\end{lemma}

n17451.content:
\begin{lemma}\label{lem:Filtration.predictable_le_prod}
  \uses{def:predictableMeasurableSpace}
  \leanok
  \lean{MeasureTheory.Filtration.predictable_le_prod}
The predictable $\sigma$-algebra on $T \times \Omega$ is a sub-$\sigma$-algebra of the product $\sigma$-algebra $\mathcal{B}(T) \otimes \mathcal{F}$~.
\end{lemma}

n17453.content:
\begin{definition}[L2 space of predictable processes]\label{def:L2Predictable}
  \uses{lem:Filtration.predictable_le_prod}
  \leanok
  \lean{ProbabilityTheory.L2Predictable}
Let $\mu$ be a measure on $T$ and $P$ a measure on $\Omega$.
We denote by $L^2(\mu, P)$ the space $L^2(T \times \Omega, \mathcal{P}, \mu \times P)$, in which $\mathcal{P}$ is the predictable $\sigma$-algebra, and the measure $\mu \times P$ is the restriction of the product measure on $\mathcal{B}(T) \otimes \mathcal{F}$ to $\mathcal{P}$~.
\end{definition}

n17454.content:
\begin{lemma}\label{lem:L2Predictable.inner_eq}
  \uses{def:L2Predictable}
For $X, Y \in L^2(\mu, P)$, we have
\begin{align*}
  \langle X, Y \rangle_{L^2(\mu, P)} = P\left[ \int_0^{\infty} \langle X_t, Y_t\rangle \: d\mu \right]
  \: .
\end{align*}
The norm is $\Vert X \Vert_{L^2(\mu, P)}^2 = P\left[ \int_0^{\infty} \Vert X_t \Vert^2 \: d\mu \right]$~.
\end{lemma}

n17455.content:
\begin{proof}
The inner product in $L^2$ spaces is defined as the integral of the pointwise inner products.
\begin{align*}
  \langle X, Y \rangle_{L^2(\mu, P)}
  &= \int_{T \times \Omega} \langle X_t(\omega), Y_t(\omega) \rangle \: d(\mu \times P)(t, \omega)
  \\
  &= P\left[ \int_0^{\infty} \langle X_t, Y_t\rangle \: d\mu \right]
  \: .
\end{align*}
\end{proof}

n17456.content:
\begin{lemma}\label{lem:simpleProcess_mem_L2Predictable}
  \uses{def:simpleProcess, def:L2Predictable}
Any simple process in $\mathcal{E}_{T, E}$ is in $L^2(\mu, P)$~.

(Lean remark: we mean that the uncurried version of its coercion to a function satisfies \texttt{MemLp})
\end{lemma}

n17457.content:
\begin{proof}
A simple process is bounded by definition.
\end{proof}

n17458.content:
\begin{lemma}\label{lem:L2Predictable.sq_norm_simpleProcess}
  \uses{def:simpleProcess, def:L2Predictable, lem:simpleProcess_mem_L2Predictable}
Let $V \in \mathcal{E}_{T, E}$ and $\mu$ a measure on $T$~.
Let $f$ be a right-continuous non-decreasing function such that for all $s < t$, $\mu((s,t]) = f(t) - f(s)$ (the CDF of $\mu$, but that's only defined for $\mathbb{R}$ in Lean).
Then
\begin{align*}
  \Vert V \Vert^2_{L^2(\mu, P)}
  &= P\left[ \sum_{k=1}^n \Vert \eta_k \Vert^2 \: (f(t_k) - f(s_k)) \right]
  \: .
\end{align*}
\end{lemma}

n17459.content:
\begin{proof}
  \uses{lem:L2Predictable.inner_eq}
TODO: this proof (and the result of the lemma) assumes that the intervals defining the simple process are disjoint.

Let $V \in \mathcal{E}_{T, E}$~, with $V_t(\omega) = \sum_{k=1}^n \eta_k(\omega) \mathbb{1}_{(s_k, t_k]}(t)$~.
\begin{align*}
  \Vert V \Vert^2_{L^2(\mu, P)}
  &= P\left[ \int_0^{\infty} \Vert V_t \Vert^2 \: d\mu \right]
  \\
  &= P\left[ \int_0^{\infty} \left\Vert \sum_{k=1}^n \eta_k \mathbb{1}_{(s_k, t_k]}(t) \right\Vert^2 \: d\mu \right]
  \\
  &= P\left[ \int_0^{\infty} \sum_{k=1}^n \Vert \eta_k \Vert^2 \mathbb{1}_{(s_k, t_k]}(t) \: d\mu \right]
  \\
  &= P\left[ \sum_{k=1}^n \Vert \eta_k \Vert^2 \: \mu((s_k, t_k]) \right]
  \\
  &= P\left[ \sum_{k=1}^n \Vert \eta_k \Vert^2 \: (f(t_k) - f(s_k)) \right]
  \: .
\end{align*}
\end{proof}

n17460.content:
\begin{definition}[L2 space with respect to a square integrable martingale]\label{def:L2M}
  \uses{def:IsSquareIntegrable, def:quadraticVariation, def:L2Predictable}
Let $M$ be a square integrable martingale. We define
\begin{align*}
  L^2(M)
  = L^2(d\langle M \rangle, P)
  = L^2(T \times \Omega, \mathcal{P}, d\langle M \rangle \times P)
\end{align*}
in which $\mathcal{P}$ is the predictable $\sigma$-algebra and $d\langle M \rangle$ is the measure induced by the quadratic variation of $M$.
\end{definition}

n17461.content:
\begin{lemma}\label{lem:sq_norm_elemStochIntegral}
  \uses{def:elemStochIntegral, def:IsSquareIntegrable, def:quadraticVariation, def:L2M}
For $V \in \mathcal{E}$ and $M \in \mathcal{M}^2$, then $V \bullet M \in \mathcal{M}^2$ (by Lemma~\ref{lem:isSquareIntegrable_elemStochIntegralBilin}) and
\begin{align*}
  \Vert V \bullet M \Vert_{\mathcal{M}^2}^2
  &= \Vert V \Vert_{L^2(M)}^2
  \: .
\end{align*}
\end{lemma}

n17462.content:
\begin{proof}
  \uses{lem:Martingale.elemStochIntegral, lem:isSquareIntegrable_elemStochIntegralBilin, lem:L2Predictable.sq_norm_simpleProcess}
  There are two steps to the proof.

  First, in order to make sense of $\Vert V \Vert_{L^2(M)}$,
  we define the natural linear map from $\mathcal{E}$ to $L^2(M)$ via \texttt{SimpleProcess.toFun}.
  (Informally, this is identifying $\mathcal{E}$ as a subset $\mathcal{E} \subseteq L^2(M)$.)
  This induces the $L^2(M)$-norm on $\mathcal{E}$, using something like \texttt{NormedSpace.induced}.

  Next, we show that integration $V \mapsto V \bullet M$ is an isometry from $\mathcal{E}$
  with the $L^2(M)$-norm, to $\mathcal{M}^2$. The proof is TODO.
\end{proof}

n17463.content:
\begin{lemma}\label{lem:integral_process_eq_zero}
  \uses{def:L2M}
Let $X\in L^2(M)$ such that $\int_0^t X_s \: d\langle M \rangle_s = 0$ for all $t \ge 0$ a.s.. Then $X = 0$ $(\mathbb{P} \times d\langle M \rangle)$-almost everywhere.
\end{lemma}

n17465.content:
\begin{lemma}[Injectivity of the integral]\label{lem:integral_process_injective}
  \uses{def:L2M}
Let $X, Y \in L^2(M)$ such that $\int_0^t X_s \: d\langle M \rangle_s = \int_0^t Y_s \: d\langle M \rangle_s$ for all $t \ge 0$ a.s.. Then $X = Y$ almost everywhere.
\end{lemma}

n17466.content:
\begin{proof}
  \uses{lem:integral_process_eq_zero}
By linearity of the integral, we have $\int_0^t (X_s - Y_s) \: d\langle M \rangle_s = 0$ for all $t \ge 0$ a.s..
Then apply Lemma~\ref{lem:integral_process_eq_zero} to $X - Y$~.
\end{proof}

n17467.content:
\begin{lemma}\label{lem:martingale_integral_of_forall_eq_zero}
  \uses{def:L2M}
Let $X \in L^2(M)$ such that $\langle X, V\rangle = 0$ for any simple process $V$. Let $A_t = \int_0^t X_s \: d\langle M \rangle_s$. Then $A_t$ is a martingale.
\end{lemma}

n17468.content:
\begin{proof}
  \uses{lem:martingale_iff_integral_elemStochIntegral_eq_zero}
By Lemma~\ref{lem:martingale_iff_integral_elemStochIntegral_eq_zero}, it is enough to show that for any bounded real simple process $V$, $\mathbb{E}[(V \bullet A)_\infty] = 0$~.
\begin{align*}
  \mathbb{E}\left[(V \bullet A)_\infty\right]
  &= \mathbb{E}\left[ \int_0^{\infty} V_t X_t \: d\langle M \rangle_t \right]
  \\
  &= \langle X, V \rangle
  \\
  &= 0
  \: .
\end{align*}
\end{proof}

n17469.content:
\begin{lemma}\label{lem:integral_eq_zero_of_forall_eq_zero}
  \uses{def:L2M}
Let $X \in L^2(M)$ such that $\langle X, V\rangle = 0$ for any simple process $V$. Then for all $t$, $\int_0^t X_s \: d\langle M \rangle_s = 0$.
\end{lemma}

n17470.content:
\begin{proof}
  \uses{thm:IsLocalMartingale.eq_zero_of_finiteVariation, lem:martingale_integral_of_forall_eq_zero, lem:Martingale.IsLocalMartingale}
$A_t := \int_0^t X_s \: d\langle M \rangle_s$ is a finite variation process such that $A_t$ is integrable for all $t \ge 0$~.
By Theorem~\ref{thm:IsLocalMartingale.eq_zero_of_finiteVariation}, it is enough to show that $A$ is a local martingale. We have by Lemma~\ref{lem:martingale_integral_of_forall_eq_zero} that $A$ is a martingale, and hence a local martingale (Lemma~\ref{lem:Martingale.IsLocalMartingale}).
\end{proof}

n17471.content:
\begin{lemma}\label{lem:dense_simpleProcess}
  \uses{def:L2M, def:simpleProcess}
The set of simple processes is dense in $L^2(M)$.
\end{lemma}

n17472.content:
\begin{proof}
  \uses{lem:integral_eq_zero_of_forall_eq_zero, lem:integral_process_eq_zero}
Since $L^2(M)$ is a Hilbert space, it is enough to show that if $X \in L^2(M)$ is orthogonal to all simple processes, then $X = 0$~.
Let $X \in L^2(M)$ such that for any simple process $V$, $\mathbb{E}\left[ \int_0^{\infty} X_t V_t \: d\langle M \rangle_t \right] = 0$~.
Let $A_t = \int_0^t X_s \: d\langle M \rangle_s$.
It suffices to show that $A = 0$ by Lemma~\ref{lem:integral_process_eq_zero}~.
This is proved in Lemma~\ref{lem:integral_eq_zero_of_forall_eq_zero}~.

In Lean, this is stated as: the natural linear map \texttt{toFun} from $\mathcal{E}$ to $L^2(M)$
is \texttt{IsDenseInducing}. The Itô isometry is then defined using \texttt{IsDenseInducing.extend}.
\end{proof}

n17473.content:
\begin{definition}[Itô isometry]\label{def:itoIsometry}
  \uses{lem:dense_simpleProcess, lem:sq_norm_elemStochIntegral, thm:hilbertSpace_L2Martingales}
Let $M \in \mathcal{M}^2$. Then the elementary stochastic integral map $\mathcal{E} \to \mathcal{M}^2$ defined by $V \mapsto V \bullet M$ extends to an isometry $L^2(M) \to \mathcal{M}^2$.
\end{definition}

n17474.content:
\begin{lemma}\label{lem:inner_itoIsometry}
  \uses{def:itoIsometry}
$\langle X \cdot M, Y \cdot M \rangle_{\mathcal{M}^2} = (XY) \cdot \langle M, N \rangle_{\mathcal{M}^2}$.
\end{lemma}

n17476.content:
\begin{definition}[$L^2_{loc}(M)$]\label{def:L2locM}
  \uses{def:L2M}
Let $M$ be a continuous local martingale.
We define $L^2_{loc}(M)$ as the space of predictable processes $X$ such that for all $t \ge 0$, $\mathbb{E}\left[ \int_0^t X_s^2 \: d\langle M \rangle_s \right] < \infty$.
\end{definition}

n17477.content:
\begin{definition}[Stochastic integral for continuous local martingales]\label{def:locStochIntegral}
  \uses{def:L2locM, def:itoIsometry, def:covariation}
Let $M$ be a continuous local martingale and let $X \in L^2_{loc}(M)$.
We define the local stochastic integral $X \cdot M$ as the unique continuous local martingale with $(X \cdot M)_0 = 0$ such that for any continuous local martingale $N$, almost surely,
\begin{align*}
  \langle X \cdot M, N \rangle = X \cdot \langle M, N \rangle
  \: .
\end{align*}
\end{definition}

n17478.content:
\begin{definition}\label{def:stochIntegral}
  \uses{def:IsSemimartingale, def:locStochIntegral}
For a continuous semi-martingale $X = M + A$ and $V \in L^2_{semi}(X)$ (to be defined) we define the stochastic integral as
\begin{align*}
  V \cdot X = V \cdot M + V \cdot A
  \: ,
\end{align*}
in which $V \cdot M$ is the local stochastic integral defined in \ref{def:locStochIntegral} and $V \cdot A$ is the Lebesgue-Stieltjes integral with respect to the locally finite variation process $A$.
\end{definition}

n17479.content:
\begin{theorem}[Integration by parts]\label{thm:integration_by_parts}
  \uses{def:IsSemimartingale, def:stochIntegral}
Let $X$ and $Y$ be two continuous semi-martingales. Then we have almost surely
\begin{align*}
  X_t Y_t - X_0 Y_0
  = (X \cdot Y)_t + (Y \cdot X)_t + [X,Y]_t
  \: .
\end{align*}
\end{theorem}

n17481.content:
\begin{theorem}[Itô's formula]\label{thm:Ito_formula}
  \uses{def:IsSemimartingale}
Let $X^1, \ldots, X^d$ be continuous semi-martingales and let $f : \mathbb{R}^d \to \mathbb{R}$ be a twice continuously differentiable function.
Then, writing $X = (X^1, \ldots, X^d)$, the process $f(X)$ is a semi-martingale and we have
\begin{align*}
  f(X_t)
  &= f(X_0)
  + \sum_{i=1}^d \int_0^t \frac{\partial f}{\partial x_i}(X_s) \: dX^i_s
  + \frac{1}{2} \sum_{i,j=1}^d \int_0^t \frac{\partial^2 f}{\partial x_i \partial x_j}(X_s) \: d[X^i, X^j]_s
  \: .
\end{align*}
\end{theorem}

